exec(open('sheet_style.py', encoding='utf-8').read())  # reuse fonts, styles, helpers
doc = SimpleDocTemplate("../pdf/Might_Guy_Canon_5e_Build.pdf", pagesize=letter, leftMargin=0.6*inch, rightMargin=0.6*inch, topMargin=0.6*inch, bottomMargin=0.7*inch, title="Might Guy (Canon) — D&D 5e Build", author="Claude")
W = letter[0] - 1.2*inch
S = []
S.append(P("Might Guy · Canon (final)", title))
S.append(P("Human · Monk (Warrior of the Eight Gates) 20 · Leaf Jōnin · the merge of two sheets, keeping what fits him best", subtitle))
S.append(HRFlowable(width="100%", thickness=1.4, color=GREEN, spaceBefore=4, spaceAfter=8))
S.append(P("<b>What came from where.</b> From the second sheet: the subclass itself (the Gates are the subclass, unlocking at levels 3, 6, 11 and 17; Gate of Healing replaces Wholeness of Body, Gate of Death replaces Quivering Palm), the databook scores, Alert, the flat strain, the two-turn Gate of Death, Daytime Tiger as a blast, Ninkame at his true size, the Kakashi tandem, the Self-Rules, the Boruto version. From the first: the arc-by-arc feat checks, Night Guy and Daytime Tiger sized to the Kisame and Madara feats, the Lotus costing its user, and the aftermath of the seventh Gate. Everything else is the 2024 Monk."))
S.append(P("Snapshot: the Fourth War, level 20, Gates closed", h2)); S.append(rule())
block = [P("Might Guy", statname),
 P("Medium Humanoid (Human), about thirty · green bodysuit, orange leg warmers, the jōnin vest, forehead protector as a belt · the italic line is seven Gates", stattag),
 P("<b>AC</b> 19 (21 from the 4th Gate) · <b>HP</b> 263 · <b>Speed</b> 60 ft, +10 per open Gate; walls and water are ground · <b>Initiative</b> +13 (Alert) · <b>Proficiency</b> +6 · <b>Focus</b> 20 (Uncanny Metabolism refills it once a day at initiative) · <b>Save DC</b> 16", stat),
 abil_table(["16 (+3)","24 (+7)","18 (+4)","10 (+0)","14 (+2)","8 (−1)"], W-24), Spacer(1,4),
 P("<b>Saves</b> all six: Str +9, Dex +13, Con +10, Int +6, Wis +8, Cha +5; 1 Focus rerolls a failure; advantage on Strength saves with any Gate open · <b>Skills</b> Acrobatics +13, Athletics +9, Insight +8, Perception +8, Survival +8", stat),
 P("<b>Defenses.</b> Deflect Attacks (reaction): any hit loses 1d10+27; at 0, 1 Focus throws it back for 2d12+7. Patient Defense (1 Focus): Dodge as a bonus action with 2d12 temporary HP. Superior Defense (3 Focus): resistance to everything but force for a minute. Evasion. Self-Restoration. <b>Eyes on the Feet:</b> a gaze or eye-contact illusion never catches him unless he chooses to look.", stat),
 P("<b>Attacks.</b> Unarmed strike +13, 1d12+7 bludgeoning or force, +1 per open Gate. Two per Attack action, three from the 3rd Gate. Flurry of Blows (1 Focus, free from the 7th): three more, each able to add a Strong Fist kick (DC 16): Leaf Strong Whirlwind knocks 15 ft away, Leaf Hurricane knocks prone, Leaf Rising Wind stops reactions. Stunning Strike once a turn (1 Focus, Con DC 16). Dynamic Entry: Charger. Sōshūga nunchaku and kunai use the martial arts die.", stat),
 P("<i><b>Seven Gates open</b> (a bonus action): speed 130 ft, +7 on every strike, AC 21, three attacks, a free Flurry, crits on 19–20, Morning Peacock and Daytime Tiger; 14 HP a turn, and afterward 3 levels of exhaustion and 1d4 hours in which he cannot move.</i>", stat),
 P("<b>Feats</b> Tough, Alert, Charger, Boon of Fortitude (+40 HP; +4 on any healing, once a turn); ASIs at 8, 12, 16 · <b>Other</b> Gate of Healing, Blue Beast (Fleet Step), Acrobatic Movement, Superior Defense, Body and Mind, Summoning: Ninkame, Self-Rules (Heroic Inspiration), the Kakashi tandem.", stat)]
box = Table([[f] for f in block], colWidths=[W]); box.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("BOX",(0,0),(-1,-1),1.0,GREEN),("LEFTPADDING",(0,0),(-1,-1),11),("RIGHTPADDING",(0,0),(-1,-1),11),("TOPPADDING",(0,0),(-1,-1),1),("BOTTOMPADDING",(0,0),(-1,-1),1),("TOPPADDING",(0,0),(-1,0),9),("BOTTOMPADDING",(0,-1),(-1,-1),9)])); S.append(box)
S.append(P("The Eight Inner Gates", h2)); S.append(rule())
S.append(P("Bonus action to open as many as he likes, in order, up to the seventh. Every open Gate: +10 ft speed and +1 damage on each unarmed strike. <b>Strain:</b> at the start of each turn he takes damage equal to the number of open Gates, doubled from the sixth on (seven Gates: 14); nothing reduces it. <b>Afterward:</b> 2 levels of exhaustion if the sixth was open, 3 if the seventh, and after the seventh he cannot move for 1d4 hours. The first five cost nothing more.", small))
gates = [("1 · Opening","Advantage on Strength checks and saves. Front Lotus."),("2 · Healing","Regains 1d12+20 when it opens (once per short rest); exhaustion waits while the Gates are open."),("3 · Life","Three attacks per Attack action. Reverse Lotus."),("4 · Pain","+2 AC: too fast to follow."),("5 · Limit","Unarmed strikes crit on 19–20."),("6 · View","Everyone within 15 ft: Str DC 16 or pushed 15 ft. Morning Peacock."),("7 · Wonder","Flurry of Blows costs no Focus. Daytime Tiger."),("8 · Death","Only once in his life, while the first seven are open; lasts until the end of his next turn. Speed 140, +8 on every strike, advantage on every attack roll (nobody at that fight could follow him), his strikes ignore resistance, resistance to all damage, immune to Frightened, Grappled, Restrained and Stunned, no strain. Evening Elephant and Night Guy. When it closes he drops to 0 HP and dies at the end of his next turn, no death saves; only a Wish, True Resurrection or the Six Paths can stop it, and the leg never heals.")]
S.append(grid([[P("Gate", cellhead), P("What it adds", cellhead)]] + [[P(a, cellb), P(b, cell)] for a, b in gates], [1.0*inch, W-1.0*inch]))
S.append(P("Techniques", h2)); S.append(rule())
techs = [("Front Lotus","1st Gate · 1 Focus · replaces one attack","Kicks a Large or smaller creature skyward and spins it head-first into the ground: 4d12 + Dex + Gates, prone. It costs him 1d10: the Lotus damages the one who uses it, which is why he made Lee promise."),
 ("Reverse Lotus","3rd Gate · 3 Focus · action","One unarmed strike with advantage: 8d12 + Dex + Gates, prone, and Con DC 16 or Stunned until his next turn. 2d10 to himself."),
 ("Morning Peacock","6th Gate · 2 Focus","Five unarmed strikes at one creature instead of three, as fire; if two or more hit, the target is Burning (1d4 fire a turn until it spends an action). It finished the copy of Kisame."),
 ("Daytime Tiger","7th Gate · 3 Focus · action · 4d10 to himself","One punch compresses the air into a tiger that bursts on a point within 120 ft: everything in a 20-ft radius makes a Dex save DC 16, taking 30d12+7 force (about 200), flung 20 ft and knocked prone on a failure, half on a success. It is air, not chakra, so Samehada cannot eat it. It beat the real Kisame. Against Madara it did nothing."),
 ("Evening Elephant","8th Gate · action","Five punches of air, each a step faster: five unarmed strikes at creatures within 120 ft for 1d12+15, 2d12+15, up to 5d12+15 (about 172), each pushing 10 ft or slamming prone."),
 ("Night Guy","8th Gate · action · once, ever","Everything he has left in one kick, his blood vapor a dragon around him: he flies his speed in a line and kicks one creature. It cannot miss and nothing reduces it: 60d12+15 force (about 405), ignoring resistance and immunity; everyone within 10 ft of his path makes a Str save DC 16 or is thrown 30 ft. Then the Gate closes."),
 ("Eyes on the Feet","from the day Itachi came to Konoha","He fights looking at the feet and reads the body from them; eye-contact genjutsu never reaches him, and he has advantage against illusions that need him to see their source."),
 ("Summoning: Ninkame · the Kakashi tandem · Self-Rules","as on the second sheet","A small talking tortoise he can kick off in midair; once a round, when Guy or Kakashi hits a creature, the other may attack it as a reaction; a rule set out loud before a task gives him Heroic Inspiration and costs him if he fails.")]
for name, tag, text in techs:
    S.append(KeepTogether([P(name, hb_name), P(tag, hb_tag), P(text, small)]))
S.append(P("The feats, checked", h2)); S.append(rule())
S.append(bullets(["<b>Part I, Itachi and Kisame.</b> Dynamic Entry on Kisame is a Charger hit for 1d12+7+1d8 and a 10-ft shove. Itachi's genjutsu needs his eyes; he gives it his feet, and Itachi leaves.",
 "<b>The Kisame copy, six Gates.</b> A 110-HP clone against Morning Peacock's five fire strikes at 1d12+13 plus a free Flurry: eight swings, five or six landing, is about 110. One turn, 12 HP of strain.",
 "<b>The real Kisame, seven Gates.</b> CR 22, 300 HP, Samehada. Daytime Tiger's 30d12+7 is about 200 on a failed Dex save; Kisame's +8 fails on a 7 or less, which is the manga's clean hit, it leaves a 300-point Kisame alive and unable to move, and the Tiger's air is the one thing the sword can't drink. He wins it, pays 4d10 and 3d10, and cannot stand up afterward.",
 "<b>Madara, the Eighth Gate.</b> CR 30 with the Ten-Tails, 700 HP (the Tarrasque's: the strongest thing in Naruto gets the strongest thing in the book), regeneration. Evening Elephant's five steps with advantage against AC 22 all land, about 172; Night Guy is about 405 with no save, no reaction and no resistance. Some 580 of 700 in two turns from a man with no chakra technique: the chest caved in, the brink, and the Ten-Tails rebuilding what is left. Then the ash, 0 HP, and Naruto."]))
S.append(P("Calibration", h2)); S.append(rule())
S.append(P("The yardstick is 5e's own ceiling. The Tarrasque has 697 hit points, so Ten-Tails Madara gets 700, and the Gate of Death is sized to what it did to him: Evening Elephant a fifth of that pool, Night Guy three fifths, the two together leaving a sliver for the Ten-Tails to rebuild. Daytime Tiger is sized the same way against a 300-point Kisame it left alive but unable to move. These are the canon numbers. For a player's table, where a no-save 405 is a delete button, drop Night Guy to 25d12+15 and the Tiger to 14d12+7 and change nothing else; that is the earlier sheet, and it is still him."))
